import { describe, expect, it } from "vitest";
import { humidityFromValues } from "./eregister-derived";
import fixture from "./metpy-humidity.fixture.json";

// Values from MetPy 1.7.1 (vapour pressure from psychrometric_vapor_pressure_wet
// with the WMO coefficient, dewpoint, relative humidity), generated by
// apps/api/fastapi/scripts/metpy_fixtures.py. The register's Magnus constants
// differ from MetPy's Bolton ones; the tolerances are the measured maxima on the
// realistic grid, with the same bounds as tests/test_eregister_metpy_oracle.py.
const VAPOUR_TOLERANCE_HPA = 0.15;
const DEW_POINT_TOLERANCE_C = 0.1;
// Whole percent in the register: 0.6 points from the constants plus rounding.
const RELATIVE_HUMIDITY_TOLERANCE = 1.1;

describe("humidityFromValues against MetPy", () => {
  it("matches every realistic fixture point within the stated tolerances", () => {
    expect(fixture.points.length).toBeGreaterThan(100);
    for (const point of fixture.points) {
      const label = `${point.airTemp}/${point.wetBulb} at ${point.stationPressure}`;
      const result = humidityFromValues({
        air_temp: point.airTemp,
        station_pressure: point.stationPressure,
        wet_bulb: point.wetBulb,
      });
      if (result === null) throw new Error(`no humidity for ${label}`);
      expect(
        Math.abs(result.vapourPressure - point.vapourHpa),
        `vapour ${label}`
      ).toBeLessThanOrEqual(VAPOUR_TOLERANCE_HPA);
      expect(
        Math.abs(result.dewPoint - point.dewPointC),
        `dew point ${label}`
      ).toBeLessThanOrEqual(DEW_POINT_TOLERANCE_C);
      expect(
        Math.abs(result.relativeHumidity - point.relativeHumidity),
        `relative humidity ${label}`
      ).toBeLessThanOrEqual(RELATIVE_HUMIDITY_TOLERANCE);
    }
  });
});
